import java.util.*;
import java.io.*;

public class Main {
    static final long MOD_A = 998244353L;
    static final long MOD_B = 1000000007L;
    static long result = 0;
    static long n_value;
    static long counter1 = 0;
    static List<Long>[] digitValues = new ArrayList[7];
    static long[] sumValues = new long[7];
    static int count2_local;
    static long[] powTen = {1L, 10L, 100L, 1000L, 10000L, 100000L, 1000000L};

    static {
        for (int i = 0; i < 7; i++) {
            digitValues[i] = new ArrayList<>();
        }
    }

    static void buildValues(int depth, long prefixSum) {
        if (depth == 7) return;
        long val = (counter1 - prefixSum + MOD_A) % MOD_A;
        digitValues[depth].add(val);
        sumValues[depth] += val;
        counter1++;
        for (int d = 0; d <= 9; d++) {
            buildValues(depth + 1, prefixSum * 10 + d);
        }
    }

    static boolean inRange(long x) {
        long half = 1000000L;
        return x * half + 999999L <= n_value && x * half * 10 > n_value;
    }

    static void traverse(int level, long num) {
        if (num > n_value) return;
        if (inRange(num)) {
            for (int i = 0; i <= 6; i++) {
                long offset = ((long)((count2_local + 1 - (num * powTen[i])) % MOD_A) + MOD_A) % MOD_A;
                List<Long> arr = digitValues[i];
                int pos = lowerBound(arr, MOD_A - offset);
                long sumVal = sumValues[i];
                long size = arr.size();
                long temp = (sumVal + offset * size - MOD_A * (size - pos)) % MOD_B;
                result = (result + temp) % MOD_B;
            }
            count2_local += counter1;
        } else {
            count2_local++;
            long tempVal = ((count2_local - num) % MOD_A + MOD_A) % MOD_A;
            result = (result + tempVal) % MOD_B;
            for (int d = 0; d <= 9; d++) {
                if (level == 0 && d == 0) continue;
                traverse(level + 1, num * 10 + d);
            }
        }
    }

    static int lowerBound(List<Long> list, long value) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= value) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n_value = Long.parseLong(br.readLine().trim());
        buildValues(0, 0);
        for (int i = 0; i <= 6; i++) {
            Collections.sort(digitValues[i]);
        }
        count2_local = -1;
        traverse(0, 0);
        System.out.println(result);
    }
}
